#include "staff_test_support.h"
#include <functional>
#include <iostream>
using namespace staff_test;
int runStaffCoreTests(){
 const std::vector<std::pair<const char*,std::function<void()>>> tests={
 {"saving unchanged named attendees switches automatic back to manual",[]{auto s=basis();const std::vector<std::string> people={"staff-opening-manager:home"};check(setStaffMeetingPeople(s,"home",people),"first selection");s.operatingMeetingSettings.attendeeMode=OperatingMeetingAttendeeMode::Auto;check(setStaffMeetingPeople(s,"home",people)&&s.operatingMeetingSettings.attendeeMode==OperatingMeetingAttendeeMode::Manual,"unchanged selection ignored mode");}},
 {"AI review renews contracts expiring before next review",[]{auto s=basis();auto q=quoteStaffAction(s,"away","staff-model:medical:1","hire",{"medical"},1);check(q.allowed&&confirmStaffAction(s,q),"AI fixture hire");for(auto& c:s.staffContracts)if(c.personId=="staff-model:medical:1")c.endDate=s.currentDate.addDays(20);s.staffPolicies.at("away").nextReviewDate=s.currentDate.addDays(1);day(s);const auto* c=activeStaffContract(s,"staff-model:medical:1");check(c&&s.currentDate.daysUntil(*c->endDate)>300,"expiry skipped between reviews");}},
 {"explicit people override role auto-choice",[]{auto s=basis();hire(s,"staff-model:coach:1",{"coach"});std::string error;check(setStaffMeetingPeople(s,"home",{"staff-model:coach:1"},&error),error);auto a=staffMeetingAttendees(s,OperatingMeetingAgendaType::General,s.operatingMeetingSettings);check(a.size()==1&&a[0].displayName=="가상 코치 후보 1","explicit people");}},
 {"meeting selection rejects unknown or other club person atomically",[]{auto s=basis();auto before=staff_test::snapshot(s);check(!setStaffMeetingPeople(s,"home",{"staff-opening-manager:away"})&&staff_test::snapshot(s)==before,"outsider attendance");}},
 {"departed meeting invitee never attends",[]{auto s=basis();check(setStaffMeetingPeople(s,"home",{"staff-opening-manager:home"}),"invite");auto q=quoteStaffAction(s,"home","staff-opening-manager:home","dismiss");check(confirmStaffAction(s,q),"dismiss");auto a=staffMeetingAttendees(s,OperatingMeetingAgendaType::General,s.operatingMeetingSettings);check(a.size()==1&&a.front().role=="owner","ghost attendee");}},
 {"automatic meeting can override saved named list",[]{auto s=basis();setStaffMeetingPeople(s,"home",{"staff-opening-manager:home"});auto settings=s.operatingMeetingSettings;settings.attendeeMode=OperatingMeetingAttendeeMode::Auto;check(staffMeetingAttendees(s,OperatingMeetingAgendaType::General,settings).size()>=3,"auto switch");}},
 {"delegation does not hire for already filled role",[]{auto s=basis();hire(s,"staff-model:director:1",{"director"});request(s);hire(s,"staff-model:medical:2",{"medical"});setStaffPolicy(s,"home",1000000,true,100000);day(s);check(s.staffRequests.front().status=="pending"&&!activeStaffContract(s,"staff-model:medical:1"),"redundant delegation");}},
 {"empty catalog is corruption not regeneration",[]{auto s=basis();s.staffPeople.clear();check(!validateStaffOperations(s).empty(),"empty staff accepted");}},
 {"activation preserves cash and legacy terms",[]{auto s=basis();check(s.club.finance.cashPence==10000000 && staffWeeklyPayroll(s,"home")==0,"legacy cash");check(activeStaffContract(s,"staff-opening-manager:home")->legacyTerms,"legacy terms");}},
 {"activation is idempotent",[]{auto s=basis();auto before=staff_test::snapshot(s);initializeStaffOperations(s);check(staff_test::snapshot(s)==before,"reinitialized");}},
 {"same seed candidates",[]{auto a=basis(),b=basis();check(staff_test::snapshot(a)==staff_test::snapshot(b),"seed");}},
 {"quote is read only",[]{auto s=basis();auto before=staff_test::snapshot(s);auto q=quoteStaffAction(s,"home","staff-model:coach:1","hire",{"coach"});check(q.allowed && staff_test::snapshot(s)==before,"quote mutation");}},
 {"hire cash and contract atomic",[]{auto s=basis();const auto cash=s.club.finance.cashPence;hire(s,"staff-model:coach:1",{"coach"});check(s.club.finance.cashPence==cash-48000 && staffWeeklyPayroll(s,"home")==12000,"hire costs");check(validateStaffOperations(s).empty(),validateStaffOperations(s));}},
 {"duplicate confirmation rejected",[]{auto s=basis();auto q=quoteStaffAction(s,"home","staff-model:coach:1","hire",{"coach"});check(confirmStaffAction(s,q),"hire");auto before=staff_test::snapshot(s);check(!confirmStaffAction(s,q)&&staff_test::snapshot(s)==before,"duplicate");}},
 {"changed date rejects stale quote",[]{auto s=basis();auto q=quoteStaffAction(s,"home","staff-model:coach:1","hire",{"coach"});day(s);auto before=staff_test::snapshot(s);check(!confirmStaffAction(s,q)&&staff_test::snapshot(s)==before,"stale");}},
 {"cash rejection unchanged",[]{auto s=basis();s.club.finance.cashPence=1;auto before=staff_test::snapshot(s);auto q=quoteStaffAction(s,"home","staff-model:coach:1","hire",{"coach"});check(!q.allowed&&!confirmStaffAction(s,q)&&staff_test::snapshot(s)==before,"cash");}},
 {"latest cash rechecked",[]{auto s=basis();auto q=quoteStaffAction(s,"home","staff-model:coach:1","hire",{"coach"});s.club.finance.cashPence=1;check(!confirmStaffAction(s,q),"cash changed");}},
 {"staff budget rejection",[]{auto s=basis();s.staffPolicies.at("home").weeklyLimitPence=100;check(!quoteStaffAction(s,"home","staff-model:coach:1","hire",{"coach"}).allowed,"limit");}},
 {"invalid and duplicate roles rejected",[]{auto s=basis();check(!quoteStaffAction(s,"home","staff-model:coach:1","hire",{"medical"}).allowed,"qualification");check(!quoteStaffAction(s,"home","staff-model:manager:1","hire",{"manager","manager"}).allowed,"duplicate role");}},
 {"no illegal contract length",[]{auto s=basis();check(!quoteStaffAction(s,"home","staff-model:coach:1","hire",{"coach"},0).allowed,"zero years");check(!quoteStaffAction(s,"home","staff-model:coach:1","hire",{"coach"},4).allowed,"four years");}},
 {"manager replacement one active leader",[]{auto s=basis();hire(s,"staff-model:manager:1",{"manager","coach"});check(staffForRole(s,"home","manager")->id=="staff-model:manager:1","leader");check(!activeStaffContract(s,"staff-opening-manager:home"),"previous active");check(validateStaffOperations(s).empty(),"manager integrity");}},
 {"manager appointment changes selection identity",[]{auto s=basis();auto f=fixture().fixtures.front();hire(s,"staff-model:manager:3",{"manager","coach"});auto t=chooseMatchTeam(s,f,true);check(t.managerName=="가상 감독 후보 3"&&t.formation=="4-3-3","manager match");}},
 {"dismiss manager caretaker keeps other workers",[]{auto s=basis();hire(s,"staff-model:coach:1",{"coach"});auto q=quoteStaffAction(s,"home","staff-opening-manager:home","dismiss");check(confirmStaffAction(s,q),"dismiss");check(!staffForRole(s,"home","manager")&&staffForRole(s,"home","coach"),"caretaker");check(chooseMatchTeam(s,fixture().fixtures.front(),true).managerName.find("공석")!=std::string::npos,"fallback");}},
 {"dismiss remainder compensation once",[]{auto s=basis();hire(s,"staff-model:coach:1",{"coach"});auto q=quoteStaffAction(s,"home","staff-model:coach:1","dismiss");check(q.compensationPence==12000*365/7,"compensation");auto cash=s.club.finance.cashPence;check(confirmStaffAction(s,q)&&s.club.finance.cashPence==cash-q.payNowPence,"dismiss cash");check(!confirmStaffAction(s,q),"double dismiss");}},
 {"insufficient severance blocks dismissal",[]{auto s=basis();hire(s,"staff-model:coach:1",{"coach"});s.club.finance.cashPence=1;check(!quoteStaffAction(s,"home","staff-model:coach:1","dismiss").allowed&&activeStaffContract(s,"staff-model:coach:1"),"free dismissal");}},
 {"renew keeps same person without duplicate payroll",[]{auto s=basis();hire(s,"staff-model:coach:1",{"coach"});auto q=quoteStaffAction(s,"home","staff-model:coach:1","renew",{},2);check(confirmStaffAction(s,q),"renew");check(staffWeeklyPayroll(s,"home")==12000&&activeStaffContract(s,"staff-model:coach:1")->endDate==s.currentDate.addMonths(24).addDays(-1),"renew term");}},
 {"multi role single payroll and efficiency penalty",[]{auto s=basis();hire(s,"staff-model:director:1",{"director","scout"});check(staffWeeklyPayroll(s,"home")==12000&&s.scouts.size()==1,"payroll");check(s.scouts.front().judgingCurrentAbility==s.staffPeople.at("staff-model:director:1").judging-5,"workload");}},
 {"role change doesn't bill twice",[]{auto s=basis();hire(s,"staff-model:director:1",{"director"});auto cash=s.club.finance.cashPence;auto q=quoteStaffAction(s,"home","staff-model:director:1","roles",{"director","scout"});check(confirmStaffAction(s,q)&&staffWeeklyPayroll(s,"home")==12000&&cash==s.club.finance.cashPence,"roles");}},
 {"scout departure cancels active observation only",[]{auto s=basis();hire(s,"staff-model:scout:1",{"scout"});ScoutingAssignment a;a.id="obs";a.scoutId="staff-model:scout:1";a.status=ScoutingAssignmentStatus::Active;s.scoutingAssignments.push_back(a);ScoutingMission m;m.id="mission";m.scoutId=a.scoutId;m.status="active";s.scoutingMissions.push_back(m);ScoutingReport r;r.playerId="home-1";s.scoutingReports.push_back(r);auto q=quoteStaffAction(s,"home","staff-model:scout:1","dismiss");check(confirmStaffAction(s,q),"dismiss");check(s.scoutingAssignments.front().status==ScoutingAssignmentStatus::Cancelled&&s.scoutingMissions.front().status=="paused"&&s.scoutingReports.size()==1,"history/task");}},
 {"renew scout keeps observation work",[]{auto s=basis();hire(s,"staff-model:scout:1",{"scout"});ScoutingAssignment a;a.id="obs";a.scoutId="staff-model:scout:1";a.status=ScoutingAssignmentStatus::Active;s.scoutingAssignments.push_back(a);auto q=quoteStaffAction(s,"home","staff-model:scout:1","renew");check(confirmStaffAction(s,q)&&s.scoutingAssignments.front().status==ScoutingAssignmentStatus::Active,"renew cancelled observation");}},
 {"seven daily wage fractions equal weekly",[]{auto s=basis();hire(s,"staff-model:coach:1",{"coach"});day(s,7);Money paid=0;for(const auto& t:s.operatingTransactions)if(t.clubId=="home"&&t.category=="staff_payroll")paid+=t.amountPence;check(paid==12000&&s.staffPolicies.at("home").remainder==0,"fractions");}},
 {"same date cannot pay twice",[]{auto s=basis();hire(s,"staff-model:coach:1",{"coach"});day(s,7);auto before=staff_test::snapshot(s);processStaffDay(s);settleOperatingDay(s);check(staff_test::snapshot(s)==before,"replay");}},
 {"payroll insufficiency becomes debt without deletion",[]{auto s=basis();hire(s,"staff-model:coach:1",{"coach"});s.club.finance.cashPence=0;day(s,7);check(operatingArrears(s,"home")==12000,"arrears");s.club.finance.cashPence=100000;day(s);check(operatingArrears(s,"home")==0,"recovery");}},
 {"accrual survives dismissal",[]{auto s=basis();hire(s,"staff-model:coach:1",{"coach"});day(s,3);const auto due=s.staffPolicies.at("home").accruedPence;auto q=quoteStaffAction(s,"home","staff-model:coach:1","dismiss");check(confirmStaffAction(s,q)&&s.staffPolicies.at("home").accruedPence==due,"lost accrued");}},
 {"new staff lowers forecast and available funds",[]{auto s=basis();auto before=forecastCash(s,"home",30);hire(s,"staff-model:coach:1",{"coach"});check(forecastCash(s,"home",30).closingPence()<before.closingPence()-48000,"forecast missing payroll");}},
 {"AI uses budget cash and staffing contracts",[]{auto s=basis();s.staffPolicies.at("away").weeklyLimitPence=100000;s.staffPolicies.at("away").nextReviewDate=s.currentDate.addDays(1);day(s);check(staffForRole(s,"away","medical")&&staffWeeklyPayroll(s,"away")>0,"AI hire missing");auto t=basis();t.aiClubMarketStates.front().finance.cashPence=0;day(t);check(!staffForRole(t,"away","medical"),"AI hidden money");}},
 {"expiration takes effect after last contract day",[]{auto s=basis();hire(s,"staff-model:coach:1",{"coach"});for(auto& c:s.staffContracts)if(c.personId=="staff-model:coach:1")c.endDate=s.currentDate.addDays(1);day(s);check(activeStaffContract(s,"staff-model:coach:1"),"early expiry");day(s);check(!activeStaffContract(s,"staff-model:coach:1")&&staffWeeklyPayroll(s,"home")==0,"late expiry");}},
 {"monthly request no automatic owner hire",[]{auto s=basis();day(s,28);check(!s.staffRequests.empty()&&!staffForRole(s,"home","medical"),"auto owner hire");auto n=s.staffRequests.size();processStaffDay(s);check(s.staffRequests.size()==n,"request repeated");}},
 {"approval creates contract and resolves once",[]{auto s=basis();auto id=request(s).id;auto q=quoteStaffAction(s,"home","staff-model:medical:1","hire",{"medical"});check(decideStaffRequest(s,id,true,"",q.token),"approval");check(!decideStaffRequest(s,id,true,"",q.token)&&s.staffRequests.front().status=="approved","twice");}},
 {"valid budget refusal respected",[]{auto s=basis();auto id=request(s).id;s.club.finance.cashPence=0;check(decideStaffRequest(s,id,false,"budget",""),"reject");check(s.staffPolicies.at("home").relationship==59,"justified penalty");}},
 {"invalid reason leaves request unchanged",[]{auto s=basis();auto id=request(s).id;auto before=staff_test::snapshot(s);check(!decideStaffRequest(s,id,false,"made-up","")&&staff_test::snapshot(s)==before,"invalid decision");}},
 {"unjustified refusal hurts relation",[]{auto s=basis();auto id=request(s).id;check(decideStaffRequest(s,id,false,"budget",""),"reject");check(s.staffPolicies.at("home").relationship<59,"invalid budget excuse");}},
 {"resignation warning not immediate and eventually leaves",[]{auto s=basis();s.staffPolicies.at("home").relationship=21;auto id=request(s).id;check(decideStaffRequest(s,id,false,"direction",""),"reject");check(staffForRole(s,"home","manager")&&s.staffPolicies.at("home").resignationDate,"warning");day(s,14);check(!staffForRole(s,"home","manager"),"no resignation");}},
 {"delegation off means no auto approval",[]{auto s=basis();hire(s,"staff-model:director:1",{"director"});auto id=request(s).id;day(s);check(s.staffRequests.front().status=="pending","default delegation");}},
 {"delegation requires actual director",[]{auto s=basis();request(s);check(setStaffPolicy(s,"home",1000000,true,50000),"policy");day(s);check(s.staffRequests.front().status=="pending","missing director");}},
 {"bounded delegation completes named request",[]{auto s=basis();hire(s,"staff-model:director:1",{"director"});request(s);check(setStaffPolicy(s,"home",1000000,true,50000),"policy");day(s);check(s.staffRequests.front().status=="approved"&&staffForRole(s,"home","medical"),"delegation not connected");}},
 {"delegation cap blocks expensive request",[]{auto s=basis();hire(s,"staff-model:director:1",{"director"});request(s);check(setStaffPolicy(s,"home",1000000,true,100),"policy");day(s);check(s.staffRequests.front().status=="pending","cap bypass");}},
 {"policy change cannot create cash",[]{auto s=basis();const auto cash=s.club.finance.cashPence;check(setStaffPolicy(s,"home",999999,true,99999)&&s.club.finance.cashPence==cash,"policy money");}},
 {"staff meetings off means none",[]{auto s=basis();day(s,40);check(s.operatingMeetings.empty(),"off meeting");}},
 {"monthly meeting happens exactly once",[]{auto s=basis();s.operatingMeetingSettings.cadence=OperatingMeetingCadence::Monthly;s.operatingMeetingSettings.nextMeetingDate=s.currentDate.addDays(2);day(s,2);check(s.operatingMeetings.size()==1,"scheduled");processStaffDay(s);check(s.operatingMeetings.size()==1,"meeting duplicate");}},
 {"meeting actual names with explicit vacancy",[]{auto s=basis();auto attendees=staffMeetingAttendees(s,OperatingMeetingAgendaType::General,s.operatingMeetingSettings);check(std::any_of(attendees.begin(),attendees.end(),[](const auto& a){return a.displayName=="Manager role";}),"name");check(std::any_of(attendees.begin(),attendees.end(),[](const auto& a){return a.displayName.find("공석")!=std::string::npos;}),"vacancy");}},
 {"manual attendee choice kept",[]{auto s=basis();auto p=s.operatingMeetingSettings;p.attendeeMode=OperatingMeetingAttendeeMode::Manual;p.includeManager=p.includeDirector=p.includeFinance=p.includeScouting=false;p.includeMedical=true;auto a=staffMeetingAttendees(s,OperatingMeetingAgendaType::General,p);check(a.size()==1&&a.front().role=="medical","manual choice");}},
 {"off/urgent cadence does not force weekly",[]{check(!nextStaffMeetingDate({1992,7,1},OperatingMeetingCadence::Off)&&!nextStaffMeetingDate({1992,7,1},OperatingMeetingCadence::UrgentOnly),"cadence");}},
 {"strong coach changes training effect",[]{auto s=basis();hire(s,"staff-model:coach:1",{"coach"});s.staffPeople.at("staff-model:coach:1").coaching=100;check(staffRoleAbility(s,"home","coach")==100,"coach effect");}},
 {"damaged ability rejected",[]{auto s=basis();s.staffPeople.begin()->second.medical=101;check(!validateStaffOperations(s).empty(),"ability validator");}},
 {"duplicate employment rejected",[]{auto s=basis();auto c=s.staffContracts.front();c.id="duplicate";s.staffContracts.push_back(c);check(!validateStaffOperations(s).empty(),"duplicate validator");}},
 {"invalid request date rejected",[]{auto s=basis();request(s).deadline={1990,1,1};check(!validateStaffOperations(s).empty(),"request validator");}},
 {"core reconstruction deterministic",[]{auto a=basis();hire(a,"staff-model:coach:1",{"coach"});auto b=a;day(a,40);day(b,13);GameState loaded=b;day(loaded,27);check(staff_test::snapshot(a)==staff_test::snapshot(loaded),"split divergence");}}
 };
 int failures=0;for(const auto& [name,run]:tests)try{run();std::cout<<"[PASS] staff "<<name<<'\n';}catch(const std::exception& e){++failures;std::cerr<<"[FAIL] staff "<<name<<": "<<e.what()<<'\n';}
 std::cout<<tests.size()-failures<<'/'<<tests.size()<<" staff tests passed\n";return failures;
}
